[{"order":1,"type":"heading","text":"Classification of Design Patterns: Creational, Structural, Behavioral"},{"order":2,"type":"paragraph","text":"Software design patterns offer reusable solutions to common software architecture problems. Popularized by the 'Gang of Four' (GoF) in their seminal 1994 book, design patterns are categorized into three distinct families based on their underlying intent and scope: Creational, Structural, and Behavioral."},{"order":3,"type":"subheading","text":"1. Creational Design Patterns"},{"order":4,"type":"paragraph","text":"Creational patterns abstract the instantiation process. They decouple a system from how its objects are created, composed, and represented. Instead of hardcoding direct object creation using standard operators (like 'new'), these patterns provide mechanism flexibility in deciding which concrete objects to instantiate for a given scenario."},{"order":5,"type":"bullet_point","text":"Singleton: Restricts a class to a single instance and provides global access to it."},{"order":6,"type":"bullet_point","text":"Factory Method: Defines an interface for creating an object, deferring actual instantiation to subclasses."},{"order":7,"type":"bullet_point","text":"Abstract Factory: Creates families of related or dependent objects without specifying concrete classes."},{"order":8,"type":"bullet_point","text":"Builder: Separates the construction of a complex object from its representation to allow step-by-step assembly."},{"order":9,"type":"bullet_point","text":"Prototype: Creates new objects by cloning a pre-existing exemplar instance."},{"order":10,"type":"code","text":"// Example of Creational Pattern: Factory Method
interface Logger {
  log(message: string): void;
}

class ConsoleLogger implements Logger {
  log(message: string): void {
    console.log("[Console] " + message);
  }
}

abstract class LoggerFactory {
  abstract createLogger(): Logger;

  logMessage(message: string): void {
    const logger = this.createLogger();
    logger.log(message);
  }
}"},{"order":11,"type":"subheading","text":"2. Structural Design Patterns"},{"order":12,"type":"paragraph","text":"Structural patterns focus on how classes and objects are composed to form larger, more flexible structures. They use inheritance to compose interfaces or implementations, and object composition to combine objects dynamically to enable new functionality while keeping the underlying system loosely coupled."},{"order":13,"type":"bullet_point","text":"Adapter: Enables objects with incompatible interfaces to collaborate by converting one interface into another."},{"order":14,"type":"bullet_point","text":"Decorator: Dynamically attaches new responsibilities to an object by wrapping it."},{"order":15,"type":"bullet_point","text":"Facade: Provides a simplified interface to a complex system or set of classes."},{"order":16,"type":"bullet_point","text":"Proxy: Supplies a surrogate or placeholder object to control or defer access to the original object."},{"order":17,"type":"bullet_point","text":"Composite: Composes objects into tree-like structures to represent part-whole hierarchies."},{"order":18,"type":"code","text":"// Example of Structural Pattern: Decorator
interface Coffee {
  getCost(): number;
}

class SimpleCoffee implements Coffee {
  getCost(): number { return 5; }
}

class MilkDecorator implements Coffee {
  constructor(private coffee: Coffee) {}
  getCost(): number {
    return this.coffee.getCost() + 2;
  }
}"},{"order":19,"type":"subheading","text":"3. Behavioral Design Patterns"},{"order":20,"type":"paragraph","text":"Behavioral patterns manage algorithms, relationships, and the assignment of responsibilities between objects. They go beyond defining object structures by characterizing complex control flow and execution pathways across multiple communicating objects."},{"order":21,"type":"bullet_point","text":"Strategy: Encapsulates a family of algorithms into interchangeable classes."},{"order":22,"type":"bullet_point","text":"Observer: Establishes a publish-subscribe mechanism to notify multiple objects of state changes."},{"order":23,"type":"bullet_point","text":"Command: Encapsulates a request as an object, allowing parameterization and queuing of requests."},{"order":24,"type":"bullet_point","text":"State: Allows an object to alter its behavior when its internal state changes."},{"order":25,"type":"code","text":"// Example of Behavioral Pattern: Strategy
interface PaymentStrategy {
  pay(amount: number): void;
}

class CreditCardPayment implements PaymentStrategy {
  pay(amount: number): void {
    console.log("Paid " + amount + " using Credit Card.");
  }
}

class PaymentContext {
  constructor(private strategy: PaymentStrategy) {}
  executePayment(amount: number): void {
    this.strategy.pay(amount);
  }
}"},{"order":26,"type":"subheading","text":"Choosing the Appropriate Category"},{"order":27,"type":"paragraph","text":"Understanding pattern categories aids architectural decision-making. When facing instantiation rigidity, turn to Creational patterns. When integrating legacy systems or forming component hierarchies, select Structural patterns. When organizing interaction logic and workflow between runtime components, rely on Behavioral patterns."}]
